  private static final double kQuat = 1e-9;

  private static void assertPose(String what, double x, double y, double z, double qw, double qx, double qy, double qz, Pose3d actual) {
    assertEquals(x, actual.getX(), kMeters, what + " x");
    assertEquals(y, actual.getY(), kMeters, what + " y");
    assertEquals(z, actual.getZ(), kMeters, what + " z");
    Quaternion q = actual.getRotation().getQuaternion();
    double dot = Math.abs(qw * q.getW() + qx * q.getX() + qy * q.getY() + qz * q.getZ());
    assertEquals(1.0, dot, kQuat, what + " rotation");
  }

  private static Pose3d asPose(Transform3d t) {
    return new Pose3d(t.getTranslation(), t.getRotation());
  }

